@Override
	public void render(Entity entityIn, float limbSwing, float limbSwingAmount, float ageInTicks, float netHeadYaw, float headPitch, float scale) {
		GlStateManager.pushMatrix();
		for(int x = 0; x < helmetParts.length; x++)
			helmetParts[x].postRender(0.0675F);
		GlStateManager.popMatrix();

		GlStateManager.pushMatrix();
		for(int x = 0; x < chestParts.length; x++)
			chestParts[x].postRender(0.0675F);
		GlStateManager.popMatrix();

		GlStateManager.pushMatrix();
		for(int x = 0; x < legParts.length; x++)
			legParts[x].postRender(0.0675F);
		GlStateManager.popMatrix();

		GlStateManager.pushMatrix();
		for(int x = 0; x < bootParts.length; x++)
			bootParts[x].postRender(0.06625F);
		GlStateManager.popMatrix();

		super.render(entityIn, limbSwing, limbSwingAmount, ageInTicks, netHeadYaw, headPitch, scale);
	}

@Override
	public void resetVisibilities() {
		helmet_mainrotation.showModel = false;
		chestplate_mainrotation.showModel = false;
		chestplate_armrotation_right.showModel = false;
		chestplate_armrotation_left.showModel = false;
		boots_right_main.showModel = false;
		boots_left_main.showModel = false;
		leggings_mainrotation.showModel = false;
		chainmail_leg_right.showModel = false;
		chainmail_leg_left.showModel = false;
	}

@Override
	public void setVisibilities(EntityEquipmentSlot slot) {
		this.resetVisibilities();

		switch(slot) {
		case HEAD:
			this.setHelmVisible();
			break;
		case CHEST:
			this.setChestVisible();
			break;
		case LEGS:
			this.setLegsVisible();
			break;
		case FEET:
			this.setBootsVisible();
			break;
		}
	}

public void setBootsVisible() {
		boots_right_main.showModel = true;
		boots_left_main.showModel = true;
	}

public void setLegsVisible() {
		chainmail_leg_right.showModel = true;
		chainmail_leg_left.showModel = true;
		leggings_mainrotation.showModel = true;
	}

public void setChestVisible() {
		chestplate_mainrotation.showModel = true;
		chestplate_armrotation_right.showModel = true;
		chestplate_armrotation_left.showModel = true;
	}

public void setHelmVisible() {
		helmet_mainrotation.showModel = true;
	}

public ModelBodyAttachment() {
		bipedLeftLeg.addChild(bipedLeftBoot);
		bipedRightLeg.addChild(bipedRightBoot);
		bipedBody.addChild(bipedWaist);
		clear(baseParts);
	}

private void clear(List<ModelRenderer> renderers) {
		for (ModelRenderer renderer : renderers) {
			renderer.cubeList.clear();
		}
	}

public void resetVisibilities() {
		for(ModelRenderer basePart : baseParts) {
			if(basePart.childModels != null) {
				for(ModelRenderer childPart : basePart.childModels) {
					if(childPart != bipedRightBoot && childPart != bipedLeftBoot && childPart != bipedWaist) {
						childPart.showModel = false;
					}
				}
			}
		}
	}

public void setVisibilities(EntityEquipmentSlot slot) {
		resetVisibilities();

		switch(slot) {
		case HEAD:
			if(bipedHead.childModels != null) {
				for(ModelRenderer childPart : bipedHead.childModels) {
					childPart.showModel = true;
				}
			}
			break;
		case CHEST:
			if(bipedBody.childModels != null) {
				for(ModelRenderer childPart : bipedBody.childModels) {
					if(childPart != bipedWaist) {
						childPart.showModel = true;
					}
				}
			}
			if(bipedRightArm.childModels != null) {
				for(ModelRenderer childPart : bipedRightArm.childModels) {
					childPart.showModel = true;
				}
			}
			if(bipedLeftArm.childModels != null) {
				for(ModelRenderer childPart : bipedLeftArm.childModels) {
					childPart.showModel = true;
				}
			}
			break;
		case LEGS:
			if(bipedRightLeg.childModels != null) {
				for(ModelRenderer childPart : bipedRightLeg.childModels) {
					if(childPart != bipedRightBoot && childPart != bipedLeftBoot) {
						childPart.showModel = true;
					}
				}
			}
			if(bipedLeftLeg.childModels != null) {
				for(ModelRenderer childPart : bipedLeftLeg.childModels) {
					if(childPart != bipedRightBoot && childPart != bipedLeftBoot) {
						childPart.showModel = true;
					}
				}
			}
			if(bipedWaist.childModels != null) {
				for(ModelRenderer childPart : bipedWaist.childModels) {
					childPart.showModel = true;
				}
			}
			break;
		case FEET:
			if(bipedRightBoot.childModels != null) {
				for(ModelRenderer childPart : bipedRightBoot.childModels) {
					childPart.showModel = true;
				}
			}
			if(bipedLeftBoot.childModels != null) {
				for(ModelRenderer childPart : bipedLeftBoot.childModels) {
					childPart.showModel = true;
				}
			}
			break;
		}
	}

